190	        int oldCharactersUsedForColumn;
191	        if (columnToSet + oldCodePointDisplayWidth < mColumns) {
192	            int oldEndOfColumnIndex = findStartOfColumn(columnToSet + oldCodePointDisplayWidth);
193	            oldCharactersUsedForColumn = oldEndOfColumnIndex - oldStartOfColumnIndex;
194	        } else {
