200	        if (newIsCombining) {
201	            int combiningCharsCount = WcWidth.zeroWidthCharsCount(mText, oldStartOfColumnIndex, oldStartOfColumnIndex + oldCharactersUsedForColumn);
202	            if (combiningCharsCount >= MAX_COMBINING_CHARACTERS_PER_COLUMN)
