210	            // modify the existing contents.
211	            // FIXME: Unassigned characters also get width=0.
212	            newCharactersUsedForColumn += oldCharactersUsedForColumn;
213	        }
214	
215	        int oldNextColumnIndex = oldStartOfColumnIndex + oldCharactersUsedForColumn;
216	        int newNextColumnIndex = oldStartOfColumnIndex + newCharactersUsedForColumn;
217	
218	        final int javaCharDifference = newCharactersUsedForColumn - oldCharactersUsedForColumn;
219	        if (javaCharDifference > 0) {
220	            // Shift the rest of the line right.
221	            int oldCharactersAfterColumn = mSpaceUsed - oldNextColumnIndex;
222	            if (mSpaceUsed + javaCharDifference > text.length) {
223	                // We need to grow the array
224	                char[] newText = new char[text.length + mColumns];
225	                System.arraycopy(text, 0, newText, 0, oldNextColumnIndex);
226	                System.arraycopy(text, oldNextColumnIndex, newText, newNextColumnIndex, oldCharactersAfterColumn);
227	                mText = text = newText;
228	            } else {
229	                System.arraycopy(text, oldNextColumnIndex, text, newNextColumnIndex, oldCharactersAfterColumn);
230	            }
231	        } else if (javaCharDifference < 0) {
232	            // Shift the rest of the line left.
233	            System.arraycopy(text, oldNextColumnIndex, text, newNextColumnIndex, mSpaceUsed - oldNextColumnIndex);
234	        }
235	        mSpaceUsed += javaCharDifference;
236	
