242	            // Replace second half of wide char with a space. Which mean that we actually add a ' ' java character.
243	            if (mSpaceUsed + 1 > text.length) {
244	                char[] newText = new char[text.length + mColumns];
245	                System.arraycopy(text, 0, newText, 0, newNextColumnIndex);
246	                System.arraycopy(text, newNextColumnIndex, newText, newNextColumnIndex + 1, mSpaceUsed - newNextColumnIndex);
247	                mText = text = newText;
248	            } else {
249	                System.arraycopy(text, newNextColumnIndex, text, newNextColumnIndex + 1, mSpaceUsed - newNextColumnIndex);
250	            }
251	            text[newNextColumnIndex] = ' ';
252	
253	            ++mSpaceUsed;
254	        } else if (oldCodePointDisplayWidth == 1 && newCodePointDisplayWidth == 2) {
255	            if (columnToSet == mColumns - 1) {
256	                throw new IllegalArgumentException("Cannot put wide character in last column");
257	            } else if (columnToSet == mColumns - 2) {
258	                // Truncate the line to the second part of this wide char:
259	                mSpaceUsed = (short) newNextColumnIndex;
260	            } else {
261	                // Overwrite the contents of the next column, which mean we actually remove java characters. Due to the
262	                // check at the beginning of this method we know that we are not overwriting a wide char.
263	                int newNextNextColumnIndex = newNextColumnIndex + (Character.isHighSurrogate(mText[newNextColumnIndex]) ? 2 : 1);
264	                int nextLen = newNextNextColumnIndex - newNextColumnIndex;
265	
266	                // Shift the array leftwards.
267	                System.arraycopy(text, newNextNextColumnIndex, text, newNextColumnIndex, mSpaceUsed - newNextNextColumnIndex);
268	                mSpaceUsed -= nextLen;
269	            }
270	        }
271	    }
