273	    boolean isBlank() {
274	        for (int charIndex = 0, charLen = getSpaceUsed(); charIndex < charLen; charIndex++)
275	            if (mText[charIndex] != ' ') return false;
276	        return true;
277	    }
278	
279	    public final long getStyle(int column) {
280	        return mStyle[column];
281	    }
